  'Keep browsing': { es: 'Seguir explorando', fr: 'Continuer à parcourir', pt: 'Continuar navegando', de: 'Weiter durchsuchen', ja: '引き続き閲覧する', zh: '继续浏览', ar: 'متابعة التصفح', hi: 'ब्राउज़ करना जारी रखें', it: 'Continua a sfogliare', ru: 'Продолжить просмотр', ko: '계속 둘러보기' },
  'You and {name} matched': { es: 'Tú y {name} hicieron match', fr: 'Vous et {name} avez matché', pt: 'Você e {name} deram match', de: 'Du und {name} haben ein Match', ja: 'あなたと{name}さんがマッチしました', zh: '您和{name}配对成功', ar: 'أنت و{name} تطابقتما', hi: 'आप और {name} मैच हो गए', it: 'Tu e {name} avete fatto match', ru: 'Вы и {name} — совпадение', ko: '나와 {name}님이 매칭되었습니다' },
  "Say hello, they're {distance} km away right now.": { es: 'Saluda, están a {distance} km de distancia ahora mismo.', fr: 'Dites bonjour, cette personne est à {distance} km en ce moment.', pt: 'Diga oi, essa pessoa está a {distance} km de distância agora.', de: 'Sag hallo, die Person ist gerade {distance} km entfernt.', ja: '挨拶しましょう。現在{distance}km離れた場所にいます。', zh: '打个招呼吧，对方现在距离您{distance}公里。', ar: 'قل مرحبًا، إنهم على بعد {distance} كم الآن.', hi: 'नमस्ते कहें, वे अभी {distance} किमी दूर हैं।', it: 'Saluta, si trova a {distance} km da te in questo momento.', ru: 'Поздоровайтесь — сейчас этот человек в {distance} км от вас.', ko: '인사해 보세요. 지금 {distance}km 떨어진 곳에 있어요.' },

