  '{nationality} nationality meetup': { es: 'Quedada de nacionalidad {nationality}', fr: 'Rencontre de nationalité {nationality}', pt: 'Encontro de nacionalidade {nationality}', de: '{nationality}-Nationalitätstreffen', ja: '{nationality}国籍の集まり', zh: '{nationality}国籍聚会', ar: 'تجمع لجنسية {nationality}', hi: '{nationality} राष्ट्रीयता मीटअप', it: 'Incontro di nazionalità {nationality}', ru: 'Встреча для национальности {nationality}', ko: '{nationality} 국적 모임' },
  'Group unavailable': { es: 'Grupo no disponible', fr: 'Groupe indisponible', pt: 'Grupo indisponível', de: 'Gruppe nicht verfügbar', ja: 'グループは利用できません', zh: '群组不可用', ar: 'المجموعة غير متاحة', hi: 'समूह अनुपलब्ध है', it: 'Gruppo non disponibile', ru: 'Группа недоступна', ko: '그룹을 사용할 수 없습니다' },
  "You've blocked the organizer of this group, so it's hidden from you.": { es: 'Has bloqueado al organizador de este grupo, por lo que está oculto para ti.', fr: 'Vous avez bloqué l’organisateur de ce groupe, il vous est donc masqué.', pt: 'Você bloqueou o organizador deste grupo, então ele está oculto para você.', de: 'Du hast den Organisator dieser Gruppe blockiert, daher ist sie für dich ausgeblendet.', ja: 'このグループの主催者をブロックしているため、非表示になっています。', zh: '您已屏蔽此群组的组织者，因此该群组对您隐藏。', ar: 'لقد حظرت منظم هذه المجموعة، لذا فهي مخفية عنك.', hi: 'आपने इस समूह के आयोजक को ब्लॉक कर दिया है, इसलिए यह आपसे छिपा है।', it: "Hai bloccato l'organizzatore di questo gruppo, quindi è nascosto per te.", ru: 'Вы заблокировали организатора этой группы, поэтому она скрыта от вас.', ko: '이 그룹의 주최자를 차단하여 그룹이 숨겨졌습니다.' },
