  "You've blocked {name}. Unblock to send messages.": { es: 'Has bloqueado a {name}. Desbloquea para enviar mensajes.', fr: 'Vous avez bloqué {name}. Débloquez pour envoyer des messages.', pt: 'Você bloqueou {name}. Desbloqueie para enviar mensagens.', de: 'Du hast {name} blockiert. Zum Senden von Nachrichten entsperren.', ja: '{name}さんをブロックしています。メッセージを送るにはブロックを解除してください。', zh: '您已屏蔽{name}。取消屏蔽后即可发送消息。', ar: 'لقد حظرت {name}. ألغِ الحظر لإرسال الرسائل.', hi: 'आपने {name} को ब्लॉक कर दिया है। संदेश भेजने के लिए अनब्लॉक करें।', it: 'Hai bloccato {name}. Sblocca per inviare messaggi.', ru: 'Вы заблокировали {name}. Разблокируйте, чтобы отправлять сообщения.', ko: '{name}님을 차단했습니다. 메시지를 보내려면 차단을 해제하세요.' },

  // --- Notifications ----------------------------------------------------
  'Likes, matches, and messages will show up here.': { es: 'Los me gusta, matches y mensajes aparecerán aquí.', fr: 'Les likes, matchs et messages apparaîtront ici.', pt: 'Curtidas, matches e mensagens aparecerão aqui.', de: 'Gefällt-mir-Angaben, Matches und Nachrichten erscheinen hier.', ja: 'いいね、マッチ、メッセージがここに表示されます。', zh: '点赞、配对和消息将显示在此处。', ar: 'ستظهر هنا الإعجابات والمطابقات والرسائل.', hi: 'लाइक, मैच और संदेश यहां दिखाई देंगे।', it: 'Mi piace, match e messaggi appariranno qui.', ru: 'Здесь появятся лайки, совпадения и сообщения.', ko: '좋아요, 매칭, 메시지가 여기에 표시됩니다.' },
  '{name} liked your post': { es: '{name} le dio me gusta a tu publicación', fr: '{name} a aimé votre publication', pt: '{name} curtiu sua publicação', de: '{name} gefällt dein Beitrag', ja: '{name}さんがあなたの投稿にいいねしました', zh: '{name}赞了您的帖子', ar: 'أعجب {name} بمنشورك', hi: '{name} ने आपकी पोस्ट पसंद की', it: 'A {name} piace il tuo post', ru: '{name} понравился ваш пост', ko: '{name}님이 회원님의 게시물을 좋아합니다' },
  '{name} swiped right on you': { es: '{name} te dio like', fr: '{name} vous a liké', pt: '{name} deu like em você', de: '{name} hat dich geliked', ja: '{name}さんがあなたにいいねしました', zh: '{name}对您表示喜欢', ar: 'أعجب بك {name}', hi: '{name} ने आपको पसंद किया', it: '{name} ti ha messo mi piace', ru: '{name} поставил(а) вам лайк', ko: '{name}님이 회원님을 좋아합니다' },
  '{name}: {preview}': { es: '{name}: {preview}', fr: '{name} : {preview}', pt: '{name}: {preview}', de: '{name}: {preview}', ja: '{name}：{preview}', zh: '{name}：{preview}', ar: '{name}: {preview}', hi: '{name}: {preview}', it: '{name}: {preview}', ru: '{name}: {preview}', ko: '{name}: {preview}' },
