  'sent you a message': { es: 'te envió un mensaje', fr: 'vous a envoyé un message', pt: 'enviou uma mensagem para você', de: 'hat dir eine Nachricht gesendet', ja: 'メッセージを送りました', zh: '给您发送了一条消息', ar: 'أرسل لك رسالة', hi: 'आपको एक संदेश भेजा', it: 'ti ha inviato un messaggio', ru: 'отправил(а) вам сообщение', ko: '메시지를 보냈습니다' },

  // --- Search -------------------------------------------------------
  'Search is locked': { es: 'La búsqueda está bloqueada', fr: 'La recherche est verrouillée', pt: 'A pesquisa está bloqueada', de: 'Suche ist gesperrt', ja: '検索はロックされています', zh: '搜索已锁定', ar: 'البحث مقفل', hi: 'खोज लॉक है', it: 'La ricerca è bloccata', ru: 'Поиск заблокирован', ko: '검색이 잠겨 있습니다' },
  'Trip passes cover up to 14 days. Renew your plan to search for other travelers.': { es: 'Los pases de viaje cubren hasta 14 días. Renueva tu plan para buscar otros viajeros.', fr: 'Les pass voyage couvrent jusqu’à 14 jours. Renouvelez votre forfait pour rechercher d’autres voyageurs.', pt: 'Os passes de viagem cobrem até 14 dias. Renove seu plano para pesquisar outros viajantes.', de: 'Reisepässe gelten für bis zu 14 Tage. Erneuere deinen Tarif, um nach anderen Reisenden zu suchen.', ja: 'トリップパスは最大14日間有効です。プランを更新して他の旅行者を検索しましょう。', zh: '旅行通行证最多可使用14天。续订套餐以搜索其他旅行者。', ar: 'تغطي تذاكر الرحلات حتى 14 يومًا. جدد خطتك للبحث عن مسافرين آخرين.', hi: 'ट्रिप पास 14 दिनों तक मान्य हैं। अन्य यात्रियों को खोजने के लिए अपनी योजना नवीनीकृत करें।', it: 'I pass viaggio coprono fino a 14 giorni. Rinnova il tuo piano per cercare altri viaggiatori.', ru: 'Тревел-пропуск действует до 14 дней. Продлите тариф, чтобы искать других путешественников.', ko: '트립 패스는 최대 14일간 이용 가능합니다. 다른 여행자를 검색하려면 요금제를 갱신하세요.' },
  'Search by name or nationality': { es: 'Buscar por nombre o nacionalidad', fr: 'Rechercher par nom ou nationalité', pt: 'Pesquisar por nome ou nacionalidade', de: 'Nach Name oder Nationalität suchen', ja: '名前または国籍で検索', zh: '按姓名或国籍搜索', ar: 'ابحث بالاسم أو الجنسية', hi: 'नाम या राष्ट्रीयता से खोजें', it: 'Cerca per nome o nazionalità', ru: 'Поиск по имени или национальности', ko: '이름 또는 국적으로 검색' },
  'No one matches that search.': { es: 'Nadie coincide con esa búsqueda.', fr: 'Personne ne correspond à cette recherche.', pt: 'Ninguém corresponde a essa pesquisa.', de: 'Niemand passt zu dieser Suche.', ja: 'その検索に一致する人はいません。', zh: '没有与该搜索匹配的人。', ar: 'لا يوجد أحد يطابق هذا البحث.', hi: 'उस खोज से कोई मेल नहीं खाता।', it: 'Nessuno corrisponde a questa ricerca.', ru: 'Никто не соответствует этому поиску.', ko: '검색 결과와 일치하는 사람이 없습니다.' },
  '{count} more result hidden': { es: '{count} resultado más oculto', fr: '{count} résultat supplémentaire masqué', pt: '{count} resultado a mais oculto', de: '{count} weiteres Ergebnis ausgeblendet', ja: 'あと{count}件の結果が非表示です', zh: '还有{count}个结果被隐藏', ar: 'نتيجة إضافية واحدة ({count}) مخفية', hi: '{count} और परिणाम छिपे हुए', it: '{count} altro risultato nascosto', ru: 'Скрыт ещё {count} результат', ko: '{count}개의 추가 결과가 숨겨짐' },
  '{count} more results hidden': { es: '{count} resultados más ocultos', fr: '{count} résultats supplémentaires masqués', pt: '{count} resultados a mais ocultos', de: '{count} weitere Ergebnisse ausgeblendet', ja: 'あと{count}件の結果が非表示です', zh: '还有{count}个结果被隐藏', ar: '{count} نتائج إضافية مخفية', hi: '{count} और परिणाम छिपे हुए', it: '{count} altri risultati nascosti', ru: 'Скрыто ещё {count} результатов', ko: '{count}개의 추가 결과가 숨겨짐' },
  'Free search is limited to {limit} people. Add a plan to see everyone.': { es: 'La búsqueda gratuita está limitada a {limit} personas. Añade un plan para ver a todos.', fr: 'La recherche gratuite est limitée à {limit} personnes. Ajoutez un forfait pour voir tout le monde.', pt: 'A pesquisa gratuita é limitada a {limit} pessoas. Adicione um plano para ver todos.', de: 'Die kostenlose Suche ist auf {limit} Personen begrenzt. Füge einen Tarif hinzu, um alle zu sehen.', ja: '無料検索は{limit}人までに制限されています。全員を見るにはプランを追加してください。', zh: '免费搜索仅限{limit}人，添加套餐即可查看所有人。', ar: 'يقتصر البحث المجاني على {limit} أشخاص. أضف خطة لرؤية الجميع.', hi: 'निःशुल्क खोज {limit} लोगों तक सीमित है। सभी को देखने के लिए योजना जोड़ें।', it: 'La ricerca gratuita è limitata a {limit} persone. Aggiungi un piano per vedere tutti.', ru: 'Бесплатный поиск ограничен {limit} людьми. Добавьте тариф, чтобы видеть всех.', ko: '무료 검색은 {limit}명으로 제한됩니다. 모두를 보려면 요금제를 추가하세요.' },

