function interpolate(template, params) {
  if (!params) return template
  return template.replace(/\{(\w+)\}/g, (_, key) => (params[key] ?? ''))
}

export function translate(text, language, params) {
  const template = !language || language === 'en' ? text : (dict[text]?.[language] ?? text)
  return interpolate(template, params)
}

export function useT() {
  const language = useStore((s) => s.currentUser?.language)
  return (text, params) => translate(text, language, params)
}

// Shared by NotificationsScreen and NotificationToasts so both describe a
// notification identically (and both get translated identically).
export function describeNotification(t, notif, actorName) {
  if (notif.type === 'post_like') return t('{name} liked your post', { name: actorName })
  if (notif.type === 'swipe_like') return t('{name} swiped right on you', { name: actorName })
  if (notif.type === 'message') {
    return t('{name}: {preview}', { name: actorName, preview: notif.preview || t('sent you a message') })
  }
  return ''
}

// Shared by MessagesScreen, NotificationsScreen, and PostDetail.
export function useTimeAgo() {
  const t = useT()
  return (iso) => {
    if (!iso) return ''
    const diff = Date.now() - new Date(iso).getTime()
    const mins = Math.floor(diff / 60000)
    if (mins < 1) return t('now')
    if (mins < 60) return t('{n}m', { n: mins })
    const hrs = Math.floor(mins / 60)
    if (hrs < 24) return t('{n}h', { n: hrs })
    return t('{n}d', { n: Math.floor(hrs / 24) })
  }
}
